def clean(df):
    df = df.drop_duplicates()
    df['island'] = df['island'].replace(['Dram', 'Torgerson'], ['Dream', 'Torgersen'])
    df['body_mass_g'] = df['body_mass_g'].str.replace(',', '').astype(float)
    df['sex'] = df['sex'].str.lower()
    return df

def answer(df):
    df = df[df['species'] == 'Adelie']
    result = df.groupby('island')['bill_length_mm'].mean().to_dict()
    return {k: v for k, v in result.items()}
